// Migra todas as cartas para o formato FSRS (idempotente)
function migrateAllCardsFSRS() {
  const walk = (arr) => Array.isArray(arr) && arr.forEach(c => c && c.id && fsrsMigrateCard(c));
  if (state.tutoria_highlight) walk(state.tutoria_highlight.cards);
  if (state.tutorias_numbered) Object.values(state.tutorias_numbered).forEach(t => t && walk(t.cards));
  if (state.custom_tutoria_folders) Object.values(state.custom_tutoria_folders).forEach(f => f && walk(f.cards));
  if (state.provas) Object.values(state.provas).forEach(p => p && walk(p.cards));
  if (state.custom_prova_folders) Object.values(state.custom_prova_folders).forEach(f => f && walk(f.cards));
  if (state.custom_root_folders) Object.values(state.custom_root_folders).forEach(f => f && walk(f.cards));
}

